------------ import ------------
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local CanvasGroup = CS.UnityEngine.CanvasGroup
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
------------ import ------------

------------ define ------------
local TakeoutVipOrderProductNodePath = "Game.MaidCoffee.TakeoutVipOrderProductNode"
local TakeoutVipOrderCatNodePath = "Game.MaidCoffee.TakeoutVipOrderCatNode"
local CountDownTime = 2592000 --30 * 86400 30天的秒数
------------ define ------------

---@class TakeoutVipOrderNext
---@field Env                            TakeoutVipOrderNext
---@field controller                        Engine.Modules.LuaBehaviour
---@field TextDesc                        UnityEngine.UI.Text
---@field TextTime                        TMPro.TextMeshProUGUI
---@field Slider                            UnityEngine.UI.Slider
---@field TextNumber                        TMPro.TextMeshProUGUI
---@field ImgIcon                        UnityEngine.RectTransform
---@field FontStyleButton                UnityEngine.RectTransform
---@field OverseaManageVipOrderExtraTaskNode    UnityEngine.RectTransform
---@field OverseaManageVipOrderLatticeNode    UnityEngine.RectTransform
---@field GridLayout                        UnityEngine.RectTransform
---@field TextTitle                        UnityEngine.UI.Text
local TakeoutVipOrderNext = Class('TakeoutVipOrderNext')

function TakeoutVipOrderNext:__init()
    self.cb = nil
    self.data = nil
    self.timerHandler = nil
    self.isEnable = true
end

function TakeoutVipOrderNext:__delete()
    self.cb = nil
    self.data = nil
    self.timerHandler = nil
    self.isEnable = true
end

function TakeoutVipOrderNext:Awake()
    ---@type UnityEngine.CanvasGroup
    local alphaGroup = KTool.GetComponent(self.OverseaManageVipOrderExtraTaskNode.gameObject, typeof(CanvasGroup))
    SetButtonAction(self.FontStyleButton, function()
        if alphaGroup and alphaGroup.alpha <= 0.5 then
            return
        end
        if self.cb and self.isEnable then
            self.cb(self.data, 2)
        end
    end)
end

function TakeoutVipOrderNext:DeleteTimer()
    if self.timerHandler then
        CDTimerModule.GetInstance():RemoveCD(self.timerHandler)
    end
    self.timerHandler = nil
end

function TakeoutVipOrderNext:OnEnable()
    self.timerHandler = CDTimerModule.GetInstance():AddCD(1, function(count, id, countElapsed)
        if not self.data then return end
        self.data.refreshTime = checkNumber(self.data.refreshTime) - countElapsed
        if self.data.refreshTime <= 5 then
            self.isEnable = false
        end
        if self.data.refreshTime <= 0 then
            --切到送外卖的状态
            self.data.status = 1 ---变成1的状态
            self:DeleteTimer()
            if self.cb then self.cb(self.data, 1) end ---正常倒计时完成
        return
        end
        self:SetProgressValue()
    end, CountDownTime, false, true, true)
end

function TakeoutVipOrderNext:OnDisable()
    self:DeleteTimer()
end

function TakeoutVipOrderNext:SetProgressValue()
    ---@type TableML.TableFile
    local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting3054)
    ---@type TableML.TableFileRow
    local tableFileRow = tableFile:GetByPrimaryKey(self.data.id)
    if tableFileRow then
        local time = checkNumber(tableFileRow:Get("time"))
        local curTime = checkNumber(self.data.refreshTime)
        self.Slider.value = (time - curTime) / time
        self.TextTime.text = second_toHHMMSS(curTime)
        local timeDelta = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(MaidCoffeeConstants.ParamsIds.VipOrderTimeDelta).num)
        local num = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(MaidCoffeeConstants.ParamsIds.VipOrderConsumeNum).num)
        local fastNum = num_floor(curTime / timeDelta) * num
        if curTime <= timeDelta then
            fastNum = num
        end
        self.TextNumber.text = tostring(fastNum)
    end
end

---FreshTrackGoods
---@param data VipOrderDojo
function TakeoutVipOrderNext:FreshTrackGoods(data)
    ---@type TableML.TableFile
    local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting3054)
    ---@type TableML.TableFileRow
    local tableFileRow = tableFile:GetByPrimaryKey(data.id)
    if tableFileRow then
        --local orderName = tableFileRow:Get("name", false)
        --self.TextTitle.text = orderName
        self:SetProgressValue()
        local curTime = checkNumber(self.data.refreshTime)
        --local time = checkNumber(tableFileRow:Get("time"))
        local timeDelta = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(MaidCoffeeConstants.ParamsIds.VipOrderTimeDelta).num)
        local fastId = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(MaidCoffeeConstants.ParamsIds.VipOrderConsumeId).num)
        local num = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(MaidCoffeeConstants.ParamsIds.VipOrderConsumeNum).num)
        local fastNum = num_floor(curTime / timeDelta) * num
        if curTime <= timeDelta then
            fastNum = num
        end
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(fastId)
        CfUtils.FillImage(self.ImgIcon, goodsVo.photoPath)
        self.TextNumber.text = tostring(fastNum)
    end
    if data.cooks then
        ----@type VipOrderDojo
        local fishDojo = nil
        KTool.DestroyGameObjectChildren(self.GridLayout.gameObject, false)
        for i, v in pairs(data.cooks) do
            if checkNumber(v.type) == 1 then
                local go = KTool.Instantiate(self.GridLayout.gameObject, self.OverseaManageVipOrderLatticeNode.gameObject, false)
                KTool.SetActive(go, true)
                ---@type TakeoutVipOrderProductNode
                local env = CfUtils.GetLuaScr(go, TakeoutVipOrderProductNodePath)
                if env then
                    env:FreshUI(v, function(n_data)
                        GameUtils.ShowCommonGoodsTipsBoard(env.ImgSelect.transform.gameObject, v.needId, true,nil,true)
                    end)
                end
            elseif checkNumber(v.type) == 2 then
                fishDojo = v
            end
        end
        -----处理猫猫鱼的逻辑
        --if fishDojo then
            KTool.SetActive(self.OverseaManageVipOrderExtraTaskNode.gameObject, true)
            ---@type TakeoutVipOrderCatNode
            local env = CfUtils.GetLuaScr(self.OverseaManageVipOrderExtraTaskNode.gameObject, TakeoutVipOrderCatNodePath)
            if env then
                env:FreshUI(fishDojo)
            end
        --end
    end
end

function TakeoutVipOrderNext:FreshUI(data, cb)
    self.data = data
    if cb then
        self.cb = cb
    end
    self:FreshTrackGoods(data)
end

function TakeoutVipOrderNext:OnDestroy()
    self:DeleteTimer()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return TakeoutVipOrderNext